from typing import Callable


class PricingStrategy:
    def __init__(self, multiplier: float):
        self.multiplier = multiplier

    def apply(self, value: float) -> float:
        return value * self.multiplier


STRATEGIES: dict[str, PricingStrategy] = {
    'A': PricingStrategy(1.1),
    'B': PricingStrategy(0.9),
    'C': PricingStrategy(1.05),
}


def calculate(data: list[dict], strategies: dict[str, PricingStrategy] | None = None) -> float:
    strategies = strategies or STRATEGIES
    total = 0.0
    for item in data:
        strategy = strategies.get(item['type'])
        if strategy:
            total += strategy.apply(item['value'])
    return total

